// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "this is yanked format from our code base could you add a format button into the input field that would make it into corrent format"
// Changes: Small Formátovať button; dimmed when the text is already formatted.
//          Edited for "could you compact this pane, make the 2 input boxes side by side, and put the theory inside expandable menu":
//          no longer absolutely positioned, sits next to the field label.
function FormatButton({ value, onFormat }: { value: string; onFormat: (value: string) => void }) {
  const formatted = formatDecls(value)
  const done = !value.trim() || formatted === value
  return (
    <button
      type="button"
      disabled={done}
      onClick={() => onFormat(formatted)}
      title="Previesť na jeden symbol na riadok (aj z C enumu)"
      className="shrink-0 rounded-full border border-white/10 bg-zinc-900/90 px-2 py-px text-[11px] text-zinc-300 transition hover:border-indigo-400/50 hover:text-indigo-200 disabled:cursor-default disabled:opacity-40"
    >
      Formátovať
    </button>
  )
}
